using System.Text.Json;
using Seeka.Engines.Profiles;
using Seeka.Managers.Access.Candidates;

namespace Seeka.ResourceAccess.Accessors;

/// <summary>
/// Reads the ESCO occupation list shipped inside this assembly. The file is
/// generated by <c>seeka-backend/scripts/import-esco.py</c> from ESCO's English CSV.
/// </summary>
internal sealed class EscoJobTitleAccess : IJobTitleAccess
{
    private const string ResourceName = "esco-occupations.json";

    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    private readonly Lazy<Task<JobTitleCatalog>> catalog = new(LoadCatalogAsync);

    public Task<JobTitleCatalog> LoadAsync(CancellationToken cancellationToken) =>
        catalog.Value.WaitAsync(cancellationToken);

    private static async Task<JobTitleCatalog> LoadCatalogAsync()
    {
        await using var stream = typeof(EscoJobTitleAccess).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"The embedded {ResourceName} is missing.");
        var occupations = await JsonSerializer.DeserializeAsync<Occupation[]>(stream, Json)
            ?? throw new InvalidOperationException($"The embedded {ResourceName} is empty.");
        return new JobTitleCatalog(occupations);
    }
}
